mapper.select:
SELECT sm.sku_code AS skuCode, DATE(o.platform_created_at) AS saleDate, SUM(oi.quantity) AS quantity FROM erp_order o INNER JOIN erp_order_item oi ON o.id = oi.order_id INNER JOIN sku_mapping sm ON oi.platform_item_id = sm.platform_item_id WHERE o.fulfillment_type = 'FBS' AND o.erp_status NOT IN ('CANCELED', 'RETURNED') AND o.platform_created_at >= #{startTime} AND o.platform_created_at < #{endTime}
AND sm.sku_code IN
#{sku}
GROUP BY sm.sku_code, DATE(o.platform_created_at)

SELECT poi.sku_code AS skuCode, (poi.quantity - IFNULL(poi.shipped_quantity, 0)) AS quantity, po.expected_delivery_date AS expectedDeliveryDate, po.order_no AS orderNo FROM wms_purchase_order po INNER JOIN wms_purchase_order_item poi ON poi.purchase_order_id = po.id WHERE po.deleted = 0 AND po.order_status IN ('CONFIRMED', 'IN_PRODUCTION') AND (poi.quantity - IFNULL(poi.shipped_quantity, 0)) > 0
AND poi.sku_code IN
#{sku}
